def least_squares(points, values, order, weights=None):
    if weights is None:
        weights = [1.0] * len(points)
    rows = [basis(u, order) for u in points]
    m = len(rows[0])
    b = [0.0] * m
    for w, row, y in zip(weights, rows, values):
        for j in range(m):
            b[j] = b[j] + w * row[j] * y
    L = cholesky(normal_matrix(rows, weights))
    return cholesky_solve(L, b)

def basis(u, order):
    terms = [1.0]
    for x in u:
        terms.append(x)
    if order in ("pure_quadratic", "quadratic"):
        for x in u:
            terms.append(x * x)
    if order == "quadratic":
        for j in range(len(u)):
            for k in range(j + 1, len(u)):
                terms.append(u[j] * u[k])
    return terms

def normal_matrix(rows, weights):
    m = len(rows[0])
    A = [[0.0] * m for j in range(m)]
    for w, row in zip(weights, rows):
        for j in range(m):
            for k in range(m):
                A[j][k] = A[j][k] + w * row[j] * row[k]
    return A

