def box_minimum(g, H, low, high):
    n = len(g)
    best = None
    best_value = None
    for face in itertools.product((-1, 0, 1), repeat=n):
        free = [i for i in range(n) if face[i] == 0]
        d = [low[i] if face[i] < 0 else high[i] for i in range(n)]
        if free:
            rhs = [-g[i] - sum(H[i][j] * d[j] for j in range(n) if face[j] != 0)
                   for i in free]
            try:
                L = cholesky([[H[i][j] for j in free] for i in free])
            except ArithmeticError:
                continue
            solution = cholesky_solve(L, rhs)
            if any(not low[i] <= x <= high[i] for i, x in zip(free, solution)):
                continue
            for i, x in zip(free, solution):
                d[i] = x
        value = quadratic_value(g, H, d)
        if best is None or value < best_value:
            best = d
            best_value = value
    return best

def quadratic_value(g, H, d):
    Hd = [dot(row, d) for row in H]
    return dot(g, d) + dot(d, Hd) / 2

