def local_quadratic(c):
    n = 1
    while 1 + 2 * n + n * (n - 1) // 2 < len(c):
        n = n + 1
    g = [c[1 + j] for j in range(n)]
    H = [[0.0] * n for j in range(n)]
    for j in range(n):
        H[j][j] = 2 * c[1 + n + j]
    position = 1 + 2 * n
    for j in range(n):
        for k in range(j + 1, n):
            H[j][k] = c[position]
            H[k][j] = c[position]
            position = position + 1
    return g, H

def region_move(optimum, anchor, width):
    move = []
    for x, a, r in zip(optimum, anchor, width):
        move.append(min(max(2 * (x - a) / r, -1.0), 1.0))
    return move

def zoom_factors(move, previous):
    factors = []
    for i in range(len(move)):
        c_hat = 0.0
        if previous is not None:
            c = move[i] * previous[i]
            c_hat = math.copysign(math.sqrt(abs(c)), c)
        gamma = (PAN * (1 + c_hat) + OSCILLATION * (1 - c_hat)) / 2
        factors.append(ZOOM + abs(move[i]) * (gamma - ZOOM))
    return factors

def pan_and_zoom(move, previous, width):
    factors = zoom_factors(move, previous)
    return [r * lam for r, lam in zip(width, factors)]

